</style><script>(()=>{const pool=['technology','design','development','interface','application','creative','business','digital','content','project','system','platform','website','product','service','solution','experience','modern','simple','useful','powerful','responsive','quality','innovation','community','workflow','process','future','creative','professional'];const lipsum='Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.';const sentence=()=>{let a=[...pool].sort(()=>Math.random()-.5).slice(0,Math.floor(Math.random()*9)+7).join(' ');return a.charAt(0).toUpperCase()+a.slice(1)+'.'};const paragraph=()=>Array.from({length:Math.floor(Math.random()*4)+4},sentence).join(' ');const output=document.getElementById('output'),type=document.getElementById('type'),amount=document.getElementById('amount'),start=document.getElementById('start'),stats=document.getElementById('stats');function generate(){let n=Math.min(100,Math.max(1,Number(amount.value)||1)),text='';if(type.value==='paragraphs')text=Array.from({length:n},paragraph).join('\n\n');else if(type.value==='sentences')text=Array.from({length:n},sentence).join(' ');else{let words=[];for(let i=0;i<n;i++)words.push(pool[Math.floor(Math.random()*pool.length)]);text=words.join(' ')+'.'}if(start.value==='yes'&&type.value!=='paragraphs')text=lipsum.split(' ').slice(0,n).join(' ')+(n>1?'.':'');else if(start.value==='yes'&&type.value==='paragraphs')text=lipsum+'\n\n'+text;output.value=text;stats.textContent=`${text.trim().split(/\s+/).filter(Boolean).length} words · ${text.length} characters`}document.getElementById('generate').onclick=generate;document.getElementById('copy').onclick=async()=>{if(!output.value){stats.textContent='Generate text first.';return}await navigator.clipboard.writeText(output.value);stats.textContent='Copied to clipboard.'};document.getElementById('clear').onclick=()=>{output.value='';stats.textContent='Cleared.'};generate()})();</script>
